/**
 * @param {string} n
 * @return {number}
 */
var minPartitions = function(n) {
    return Math.max(...n.split('').map(Number));
};

/**
 * @param {string} n
 * @return {number}
 */
var minPartitions = function(n) {
    let max = 0;

    for (const char of n) {
        const num = Number(char);

        if (num > max) {
            max = num;

            if (max === 9) return 9;
        }
    }

    return max;
};

/**
 * @param {string} n
 * @return {number}
 */
var minPartitions = function(n) {
    let max = '0';

    for (const char of n) {
        if (char > max) {
            max = char;

            if (max === '9') return 9;
        }
    }

    return Number(max);
};

/**
 * @param {string} n
 * @return {number}
 */
var minPartitions = function(n) {
    for (let i = 9; i >= 2; i--) {
        if (n.match(RegExp(i))) {
            return i;
        }
    }
    return 1;
};
